parameters.jsCode:
const body = $input.first().json.body || {};
const rawEmail = (body.email || '').trim().toLowerCase();
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const isValidEmail = emailRegex.test(rawEmail);
let domain = '';
if (isValidEmail) {
  domain = rawEmail.split('@')[1];
}

const genericDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com', 'proton.me'];
const isCorporate = domain ? !genericDomains.includes(domain) : false;

return [{
  json: {
    leadId: body.leadId || body.id || null,
    name: (body.name || '').trim(),
    email: rawEmail,
    company: (body.company || '').trim(),
    message: (body.message || '').trim(),
    domain: domain,
    isCorporate: isCorporate,
    isValidEmail: isValidEmail,
    ingestedAt: new Date().toISOString()
  }
}];

