parameters.jsCode:
const rawContent = $input.first().json.message?.content || $input.first().json.text || '{}';
let parsedAi = {};

try {
  parsedAi = typeof rawContent === 'string' ? JSON.parse(rawContent) : rawContent;
} catch (e) {
  parsedAi = {
    lead_score: 0,
    priority_tier: 'LOW',
    fit_reasoning: 'Failed to parse AI evaluation output.',
    recommended_action: 'AUTO_REJECT'
  };
}

const metadata = $('Sanitizer & Extractor').first().json;

return [{
  json: {
    leadId: metadata.leadId,
    email: metadata.email,
    name: metadata.name,
    company: metadata.company,
    isCorporate: metadata.isCorporate,
    qualification: {
      score: parsedAi.lead_score ?? 0,
      priorityTier: parsedAi.priority_tier || 'LOW',
      reasoning: parsedAi.fit_reasoning || 'No evaluation rationale provided.',
      recommendedAction: parsedAi.recommended_action || 'NURTURE'
    },
    evaluatedAt: new Date().toISOString()
  }
}];
